import java.util.*;

public class Main {
    public static int N = (int) 2e6 + 10;
    public static int n, m = 0;
    public static int[] prime = new int[N];
    public static boolean[] st = new boolean[N];
    public static int[] pre, a, cnt;

    public static void getPrime() {
        for (int i = 2; i < N; i++) {
            if (!st[i]) {
                prime[m++] = i;
            }
            for (int j = 0; prime[j] <= (N - 1) / i; j++) {
                st[prime[j] * i] = true;
                if (i % prime[j] == 0) {
                    break;
                }
            }
        }
    }

    public static int find(int[] pre, int x) {
        if (pre[x] == x) {
            return x;
        }
        return pre[x] = find(pre, pre[x]);
    }

    public static int kruskal(int root) {
        List<int[]> edges = new ArrayList<>();
        List<Integer> nodes = new ArrayList<>();
        for (int i = 0; i < n; ++i)
            if (find(pre, i) == root) {
                nodes.add(i);
            }
        int tn = nodes.size();
        for (int i = 0; i < tn; ++i) {
            for (int j = i + 1; j < tn; ++j)
                if (!st[a[nodes.get(i)] + a[nodes.get(j)]]) {
                    edges.add(new int[] { a[nodes.get(i)] + a[nodes.get(j)], i, j });
                }
        }
        int[] t_pre = new int[tn];
        for (int i = 0; i < tn; ++i) {
            t_pre[i] = i;
        }
        Collections.sort(edges, (a, b) -> a[0] - b[0]);
        int ans = 0;
        for (int[] e : edges) {
            int u = find(t_pre, e[1]), v = find(t_pre, e[2]);
            if (u != v) {
                t_pre[u] = v;
                ans += e[0];
            }
        }
        return ans;
    }


    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        getPrime();
        a = new int[n];
        pre = new int[n];
        cnt = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            pre[i] = i;
            cnt[i] = 1;
        }
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j)
                if (!st[a[i] + a[j]]) {
                    int u = find(pre, i), v = find(pre, j);
                    if (u != v) {
                        pre[u] = v;
                        cnt[v] += cnt[u];
                    }
                }
        }
        int mx_cnt = 0;
        for (int i = 0; i < n; ++i) {
            mx_cnt = Math.max(mx_cnt, cnt[i]);
        }
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < n; ++i)
            if (find(pre, i) == i && cnt[i] == mx_cnt) {
                ans = Math.min(ans, kruskal(i));
            }
        System.out.println(ans);
    }
}
