import sys

def sieve(limit):
    """返回长度为 limit+1 的列表 is_prime，is_prime[x] 为 True 表示 x 是素数"""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return is_prime

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        # 按大小合并，保持平衡
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        self.size[rx] += self.size[ry]

def kruskal(nodes, a, is_prime):
    """对连通分量内的节点 nodes 求最小生成树总权值"""
    m = len(nodes)
    edges = []
    # 枚举分量内所有点对
    for i in range(m):
        for j in range(i + 1, m):
            u, v = nodes[i], nodes[j]
            s = a[u] + a[v]
            if is_prime[s]:
                edges.append((s, i, j))
    edges.sort(key=lambda x: x[0])
    uf = UnionFind(m)
    total = 0
    edges_used = 0
    for w, i, j in edges:
        if uf.find(i) != uf.find(j):
            uf.union(i, j)
            total += w
            edges_used += 1
            if edges_used == m - 1:
                break
    return total

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    max_sum = max(a) * 2 if a else 0
    limit = max(2000000, max_sum)  # 保证至少覆盖 2e6
    is_prime = sieve(limit)

    uf = UnionFind(n)
    # 建图，合并连通分量
    for i in range(n):
        for j in range(i + 1, n):
            if is_prime[a[i] + a[j]]:
                uf.union(i, j)

    # 统计连通分量大小
    comp_size = {}
    for i in range(n):
        root = uf.find(i)
        comp_size[root] = uf.size[root]  # 已经通过 union 维护 size，也可以用 comp_size[root]=uf.size[root]
    if not comp_size:
        print(0)
        return
    max_size = max(comp_size.values())

    # 找出所有大小为 max_size 的连通分量的根
    roots = [r for r, sz in comp_size.items() if sz == max_size]

    ans = float('inf')
    for root in roots:
        # 提取该分量内的所有节点
        nodes = [i for i in range(n) if uf.find(i) == root]
        mst_weight = kruskal(nodes, a, is_prime)
        if mst_weight < ans:
            ans = mst_weight
    print(ans)

if __name__ == "__main__":
    main()
