import java.util.*;

public class Main {
    static final int MAX_VAL = 2000000;
    static boolean[] isPrime;

    // 素数筛
    static void sieve(int limit) {
        isPrime = new boolean[limit + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= limit; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= limit; j += i) {
                    isPrime[j] = false;
                }
            }
        }
    }

    // 并查集
    static class UnionFind {
        int[] parent, size;
        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
        void union(int x, int y) {
            int rx = find(x), ry = find(y);
            if (rx == ry) return;
            if (size[rx] < size[ry]) {
                int tmp = rx; rx = ry; ry = tmp;
            }
            parent[ry] = rx;
            size[rx] += size[ry];
        }
    }

    // Kruskal 求连通分量最小生成树
    static int kruskal(List<Integer> nodes, int[] a) {
        int m = nodes.size();
        List<int[]> edges = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                int u = nodes.get(i), v = nodes.get(j);
                int sum = a[u] + a[v];
                if (isPrime[sum]) {
                    edges.add(new int[]{sum, i, j});
                }
            }
        }
        edges.sort(Comparator.comparingInt(e -> e[0]));
        UnionFind uf = new UnionFind(m);
        int total = 0;
        int edgesUsed = 0;
        for (int[] e : edges) {
            if (uf.find(e[1]) != uf.find(e[2])) {
                uf.union(e[1], e[2]);
                total += e[0];
                edgesUsed++;
                if (edgesUsed == m - 1) break;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int maxAi = 0;
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            if (a[i] > maxAi) maxAi = a[i];
        }
        int limit = Math.max(MAX_VAL, maxAi * 2);
        sieve(limit);

        UnionFind uf = new UnionFind(n);
        // 枚举所有点对合并
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isPrime[a[i] + a[j]]) {
                    uf.union(i, j);
                }
            }
        }

        // 统计连通分量大小
        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = uf.find(i);
            compSize.put(root, uf.size[root]);
        }
        int maxSize = 0;
        for (int sz : compSize.values()) {
            if (sz > maxSize) maxSize = sz;
        }

        int ans = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : compSize.entrySet()) {
            if (entry.getValue() == maxSize) {
                int root = entry.getKey();
                List<Integer> nodes = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (uf.find(i) == root) nodes.add(i);
                }
                int mst = kruskal(nodes, a);
                if (mst < ans) ans = mst;
            }
        }
        System.out.println(ans);
    }
}
