// 对分量 nodes 求最小生成树总权值
int kruskal(const vector<int>& nodes, const vector<int>& a) {
    int m = nodes.size();
    vector<tuple<int, int, int>> edges; // (weight, u_idx, v_idx)
    for (int i = 0; i < m; ++i) {
        for (int j = i + 1; j < m; ++j) {
            int u = nodes[i], v = nodes[j];
            int sum = a[u] + a[v];
            if (isPrime[sum]) {
                edges.emplace_back(sum, i, j);
            }
        }
    }
    sort(edges.begin(), edges.end());
    UnionFind uf(m);
    int total = 0, edgesUsed = 0;
    for (auto [w, i, j] : edges) {
        if (uf.find(i) != uf.find(j)) {
            uf.unite(i, j);
            total += w;
            ++edgesUsed;
            if (edgesUsed == m - 1) break;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n);
    int maxAi = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (a[i] > maxAi) maxAi = a[i];
    }
    int limit = max(MAX_VAL, maxAi * 2);
    sieve(limit);

    UnionFind uf(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (isPrime[a[i] + a[j]]) {
                uf.unite(i, j);
            }
        }
    }

    unordered_map<int, int> compSize; // root -> size
    for (int i = 0; i < n; ++i) {
        int root = uf.find(i);
        compSize[root] = uf.sz[root];
    }
    int maxSize = 0;
    for (auto& p : compSize) {
        if (p.second > maxSize) maxSize = p.second;
    }

    int ans = INT_MAX;
    for (auto& p : compSize) {
        if (p.second == maxSize) {
            int root = p.first;
            vector<int> nodes;
            for (int i = 0; i < n; ++i) {
                if (uf.find(i) == root) nodes.push_back(i);
            }
            int mst = kruskal(nodes, a);
            if (mst < ans) ans = mst;
        }
    }
    cout << ans << "\n";
    return 0;
}
